package marketdata

import (
	"bytes"
	"cmp"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// marketdata.json.gz is generated by tools/build_marketdata.py from BLS OEWS
// (pay by occupation and area) and BEA Regional Price Parities (cost of living).
//
//go:embed marketdata.json.gz
var marketDataGz []byte

var percentilePoints = [5]float64{10, 25, 50, 75, 90}

const (
	medianPoint  = 2    // percentilePoints[medianPoint] is the 50th percentile
	NationalArea = "US" // the area code for the whole United States
)

type SourceInfo struct {
	Name    string `json:"name"`
	Release string `json:"release"`
	URL     string `json:"url"`
	Note    string `json:"note"`
}

type MarketArea struct {
	Title      string   `json:"title"`
	Type       string   `json:"type"` // national, state, metro, nonmetro
	State      string   `json:"state"`
	RPP        float64  `json:"rpp"`
	RPPHousing *float64 `json:"rppHousing"`
	RPPLevel   string   `json:"rppLevel"`
}

type MarketData struct {
	Sources     map[string]SourceInfo
	Built       string
	Occupations map[string]string
	Areas       map[string]MarketArea
	// Wages[area][occupation] = annual p10, p25, p50, p75, p90; nil = not published, -1 = top-coded.
	Wages map[string]map[string][]*int64
}

type MarketResult struct {
	Found      bool     `json:"found"`
	Percentile float64  `json:"percentile"`
	Qualifier  string   `json:"qualifier"` // "" exact estimate, "below" = under the lowest point, "above" = at/over the highest known point
	Points     [5]int64 `json:"points"`    // 0 = not published, -1 = top-coded (≥ $239,200)
	Level      string   `json:"level"`     // area, state, national
	AreaCode   string   `json:"areaCode"`
	AreaTitle  string   `json:"areaTitle"`
	OccCode    string   `json:"occCode"`
	OccTitle   string   `json:"occTitle"`
}

// Median is the 50th-percentile wage (0 when not published).
func (m MarketResult) Median() int64 { return m.Points[medianPoint] }

type Option struct {
	Code  string `json:"code"`
	Title string `json:"title"`
	State string `json:"state"`
	Type  string `json:"type"`
}

var (
	marketOnce sync.Once
	marketData *MarketData
	marketErr  error
)

// Load decodes the embedded dataset once.
func Load() (*MarketData, error) {
	marketOnce.Do(func() {
		zr, err := gzip.NewReader(bytes.NewReader(marketDataGz))
		if err != nil {
			marketErr = fmt.Errorf("market data: %w", err)
			return
		}
		defer zr.Close()
		var raw struct {
			Meta struct {
				Built   string                `json:"built"`
				Sources map[string]SourceInfo `json:"sources"`
			} `json:"meta"`
			Occupations map[string]string              `json:"occupations"`
			Areas       map[string]MarketArea          `json:"areas"`
			Wages       map[string]map[string][]*int64 `json:"wages"`
		}
		if err := json.NewDecoder(zr).Decode(&raw); err != nil {
			marketErr = fmt.Errorf("market data: %w", err)
			return
		}
		marketData = &MarketData{
			Sources: raw.Meta.Sources, Built: raw.Meta.Built,
			Occupations: raw.Occupations, Areas: raw.Areas, Wages: raw.Wages,
		}
	})
	return marketData, marketErr
}

// stateAreaCode returns the OEWS code of the state-level area for a 2-letter state.
func (md *MarketData) stateAreaCode(state string) string {
	for code, a := range md.Areas {
		if a.Type == "state" && a.State == state {
			return code
		}
	}
	return ""
}

// MarketPosition places a base salary on the published percentile curve for an
// occupation, trying the area, then its state, then the national figures.
func (md *MarketData) MarketPosition(occ, area string, base int64) MarketResult {
	res := MarketResult{OccCode: occ, OccTitle: md.Occupations[occ]}
	candidates := []struct{ code, level string }{{area, "area"}}
	if a, ok := md.Areas[area]; ok && a.Type != "state" && a.Type != "national" {
		candidates = append(candidates, struct{ code, level string }{md.stateAreaCode(a.State), "state"})
	} else if ok && a.Type == "state" {
		candidates[0].level = "state"
	}
	candidates = append(candidates, struct{ code, level string }{NationalArea, "national"})

	for _, c := range candidates {
		if c.code == "" {
			continue
		}
		pts, ok := md.Wages[c.code][occ]
		if !ok {
			continue
		}
		if c.code == NationalArea {
			c.level = "national"
		}
		res.Found, res.Level, res.AreaCode, res.AreaTitle = true, c.level, c.code, md.Areas[c.code].Title
		for i := range res.Points {
			if i < len(pts) && pts[i] != nil {
				res.Points[i] = *pts[i]
			}
		}
		res.Percentile, res.Qualifier = interpolatePercentile(res.Points, base)
		return res
	}
	return res
}

func interpolatePercentile(points [5]int64, base int64) (float64, string) {
	type known struct {
		pct float64
		val int64
	}
	var ks []known
	for i, v := range points {
		if v > 0 {
			ks = append(ks, known{percentilePoints[i], v})
		}
	}
	if len(ks) == 0 {
		// Every point top-coded: the base is somewhere at or below the cap.
		return 10, "below"
	}
	if base < ks[0].val {
		return ks[0].pct, "below"
	}
	for i := 0; i+1 < len(ks); i++ {
		lo, hi := ks[i], ks[i+1]
		if base >= lo.val && base <= hi.val {
			if hi.val == lo.val {
				return lo.pct, ""
			}
			frac := float64(base-lo.val) / float64(hi.val-lo.val)
			return lo.pct + frac*(hi.pct-lo.pct), ""
		}
	}
	last := ks[len(ks)-1]
	if base == last.val {
		return last.pct, ""
	}
	return last.pct, "above"
}

// CostOfLiving returns the BEA price index (US = 100) for an area and which level it came from.
func (md *MarketData) CostOfLiving(area string) (float64, string) {
	if a, ok := md.Areas[area]; ok && a.RPP > 0 {
		return a.RPP, a.RPPLevel
	}
	return 100, "national"
}

func searchOptions(q string, all []Option) []Option {
	q = strings.ToLower(strings.TrimSpace(q))
	var prefix, contains []Option
	for _, o := range all {
		title := strings.ToLower(o.Title)
		switch {
		case q == "":
			contains = append(contains, o)
		case strings.HasPrefix(title, q) || o.Code == q:
			prefix = append(prefix, o)
		case strings.Contains(title, q) || strings.Contains(o.Code, q):
			contains = append(contains, o)
		}
	}
	byTitle := func(s []Option) { sort.Slice(s, func(i, j int) bool { return s[i].Title < s[j].Title }) }
	byTitle(prefix)
	byTitle(contains)
	out := append(prefix, contains...)
	if len(out) > 30 {
		out = out[:30]
	}
	if out == nil {
		out = []Option{}
	}
	return out
}

func (md *MarketData) SearchOccupations(q string) []Option {
	all := make([]Option, 0, len(md.Occupations))
	for code, title := range md.Occupations {
		all = append(all, Option{Code: code, Title: title})
	}
	return searchOptions(q, all)
}

func (md *MarketData) SearchAreas(q string) []Option {
	all := make([]Option, 0, len(md.Areas))
	for code, a := range md.Areas {
		title := a.Title
		if a.Type == "national" {
			title = "Remote / United States"
		}
		all = append(all, Option{Code: code, Title: title, State: a.State, Type: a.Type})
	}
	return searchOptions(q, all)
}

// GuessArea maps free-text job locations like "Denver, CO" or "Remote" to an area code.
// It returns "" when nothing sensible matches.
func (md *MarketData) GuessArea(location string) string {
	text := strings.ToLower(strings.TrimSpace(location))
	if text == "" {
		return ""
	}
	if strings.Contains(text, "remote") {
		return NationalArea
	}
	city, state := text, ""
	if i := strings.LastIndex(text, ","); i >= 0 {
		city = strings.TrimSpace(text[:i])
		state = strings.ToUpper(strings.TrimSpace(text[i+1:]))
		if len(state) > 2 {
			state = state[:2]
		}
	}
	if city != "" {
		var matches []string
		for code, a := range md.Areas {
			if a.Type != "metro" {
				continue
			}
			parts := strings.SplitN(strings.ToLower(a.Title), ",", 2)
			if len(parts) < 2 || (state != "" && !strings.Contains(strings.ToUpper(parts[1]), state)) {
				continue
			}
			for _, name := range strings.Split(parts[0], "-") {
				if strings.TrimSpace(name) == city {
					matches = append(matches, code)
					break
				}
			}
		}
		if len(matches) > 0 {
			sort.Strings(matches)
			return matches[0]
		}
	}
	if state != "" {
		return md.stateAreaCode(state)
	}
	return ""
}

// EstimateLocation picks the pay area and tax state for a job: the area its
// location names, else the user's home area. Remote (national) jobs are taxed
// in the user's home state. state is "" when no single state applies.
func (md *MarketData) EstimateLocation(jobLocation, homeArea string) (area, state string) {
	area = cmp.Or(md.GuessArea(jobLocation), homeArea)
	stateArea := area
	if area == NationalArea {
		stateArea = homeArea
	}
	state = md.Areas[stateArea].State
	if state == NationalArea {
		state = ""
	}
	return area, state
}
